CREATE TYPE public.proc_supplier_status AS ENUM ('prospective','application_submitted','compliance_review','finance_review','approved','active','suspended','blacklisted','archived');
CREATE TYPE public.proc_request_status AS ENUM ('draft','submitted','department_approved','procurement_approved','finance_approved','rejected','cancelled','converted');
CREATE TYPE public.proc_order_status AS ENUM ('draft','submitted','approved','rejected','ordered','partially_received','completed','cancelled');
CREATE OR REPLACE FUNCTION public.proc_can_read(_company UUID) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_any_role(_company, ARRAY['admin','procurement_manager','procurement_officer','finance_manager','finance_officer','warehouse_manager','fleet_manager','department_manager','operations_manager','viewer']::public.app_role[]); $$;
CREATE OR REPLACE FUNCTION public.proc_can_manage(_company UUID) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_any_role(_company, ARRAY['admin','procurement_manager','procurement_officer']::public.app_role[]); $$;
CREATE OR REPLACE FUNCTION public.proc_can_approve(_company UUID) RETURNS BOOLEAN LANGUAGE SQL STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_any_role(_company, ARRAY['admin','procurement_manager','finance_manager','finance_officer','department_manager','operations_manager']::public.app_role[]); $$;
CREATE TABLE public.proc_suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, supplier_type TEXT NOT NULL CHECK (supplier_type IN ('vehicle_parts','fuel','tyres','warehouse_equipment','ppe','office_supplies','it_equipment','maintenance','logistics_services','contractors','general')), name TEXT NOT NULL, registration_number TEXT, tax_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, banking_metadata JSONB NOT NULL DEFAULT '{}'::jsonb, contacts JSONB NOT NULL DEFAULT '[]'::jsonb, branches JSONB NOT NULL DEFAULT '[]'::jsonb, payment_terms TEXT, currency_code TEXT NOT NULL DEFAULT 'ZAR', preferred BOOLEAN NOT NULL DEFAULT false, rating NUMERIC(4,2), status public.proc_supplier_status NOT NULL DEFAULT 'prospective', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,name));
CREATE TABLE public.proc_supplier_compliance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, supplier_id UUID NOT NULL REFERENCES public.proc_suppliers(id) ON DELETE CASCADE, compliance_type TEXT NOT NULL CHECK (compliance_type IN ('insurance','tax_clearance','bbbee','safety_certificate','iso_certificate','contract')), expires_on DATE, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','valid','expiring','expired','rejected')), document_id UUID REFERENCES public.documents(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.proc_supplier_contracts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, supplier_id UUID NOT NULL REFERENCES public.proc_suppliers(id) ON DELETE CASCADE, title TEXT NOT NULL, starts_on DATE, expires_on DATE, preferred_pricing JSONB NOT NULL DEFAULT '{}'::jsonb, volume_discounts JSONB NOT NULL DEFAULT '[]'::jsonb, document_id UUID REFERENCES public.documents(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','expired','terminated','archived')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.proc_purchase_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, department_id UUID, requester_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','critical')), items JSONB NOT NULL DEFAULT '[]'::jsonb, estimated_cost NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (estimated_cost >= 0), required_date DATE, justification TEXT NOT NULL, attachments_metadata JSONB NOT NULL DEFAULT '[]'::jsonb, cost_centre_id UUID, status public.proc_request_status NOT NULL DEFAULT 'draft', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.proc_purchase_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, request_id UUID REFERENCES public.proc_purchase_requests(id) ON DELETE SET NULL, supplier_id UUID NOT NULL REFERENCES public.proc_suppliers(id) ON DELETE RESTRICT, vehicle_id UUID REFERENCES public.vehicles(id) ON DELETE SET NULL, warehouse_id UUID, order_number TEXT NOT NULL, items JSONB NOT NULL DEFAULT '[]'::jsonb, total_amount NUMERIC(14,2) NOT NULL DEFAULT 0 CHECK (total_amount >= 0), currency_code TEXT NOT NULL DEFAULT 'ZAR', required_date DATE, ordered_at TIMESTAMPTZ, status public.proc_order_status NOT NULL DEFAULT 'draft', document_id UUID REFERENCES public.documents(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,order_number));
CREATE TABLE public.proc_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, entity_type TEXT NOT NULL CHECK (entity_type IN ('purchase_request','purchase_order')), entity_id UUID NOT NULL, approval_stage TEXT NOT NULL CHECK (approval_stage IN ('department','procurement','finance','executive')), decision TEXT NOT NULL CHECK (decision IN ('approved','rejected')), reason TEXT, approver_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE public.proc_receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, purchase_order_id UUID NOT NULL REFERENCES public.proc_purchase_orders(id) ON DELETE CASCADE, warehouse_id UUID, receipt_number TEXT NOT NULL, received_items JSONB NOT NULL DEFAULT '[]'::jsonb, rejected_items JSONB NOT NULL DEFAULT '[]'::jsonb, damaged_items JSONB NOT NULL DEFAULT '[]'::jsonb, backorder_items JSONB NOT NULL DEFAULT '[]'::jsonb, receiving_note_document_id UUID REFERENCES public.documents(id) ON DELETE SET NULL, received_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,receipt_number));
CREATE TABLE public.proc_supplier_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, supplier_id UUID NOT NULL REFERENCES public.proc_suppliers(id) ON DELETE RESTRICT, purchase_order_id UUID REFERENCES public.proc_purchase_orders(id) ON DELETE SET NULL, invoice_number TEXT NOT NULL, amount NUMERIC(14,2) NOT NULL, due_date DATE, status TEXT NOT NULL DEFAULT 'outstanding' CHECK (status IN ('outstanding','approved','paid','disputed','archived')), document_id UUID REFERENCES public.documents(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(company_id,invoice_number));
CREATE TABLE public.proc_audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE, entity_type TEXT NOT NULL, entity_id UUID NOT NULL, event_type TEXT NOT NULL, actor_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['proc_suppliers','proc_supplier_compliance','proc_supplier_contracts','proc_purchase_requests','proc_purchase_orders','proc_supplier_invoices'] LOOP EXECUTE format('CREATE TRIGGER %I_updated BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_updated_at()',t,t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (public.proc_can_read(company_id))',t||'_read',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO authenticated USING (public.proc_can_manage(company_id)) WITH CHECK (public.proc_can_manage(company_id))',t||'_manage',t); END LOOP; FOREACH t IN ARRAY ARRAY['proc_approvals','proc_receipts','proc_audit_logs'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t); EXECUTE format('GRANT ALL ON public.%I TO service_role',t); EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING (public.proc_can_read(company_id))',t||'_read',t); END LOOP; END $$;
GRANT INSERT ON public.proc_approvals, public.proc_receipts TO authenticated;
CREATE POLICY proc_approvals_write ON public.proc_approvals FOR INSERT TO authenticated WITH CHECK (public.proc_can_approve(company_id));
CREATE POLICY proc_receipts_write ON public.proc_receipts FOR INSERT TO authenticated WITH CHECK (public.proc_can_manage(company_id) OR public.has_role(company_id,'warehouse_manager'::public.app_role));
CREATE OR REPLACE FUNCTION public.proc_log(_company UUID,_type TEXT,_id UUID,_event TEXT,_data JSONB DEFAULT '{}'::jsonb) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x UUID; BEGIN INSERT INTO public.proc_audit_logs(company_id,entity_type,entity_id,event_type,actor_id,metadata) VALUES(_company,_type,_id,_event,auth.uid(),_data) RETURNING id INTO x; RETURN x; END; $$;
CREATE OR REPLACE FUNCTION public.proc_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND current_setting('proc.workflow',true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'Use procurement workflow functions to change status'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER proc_supplier_guard BEFORE UPDATE ON public.proc_suppliers FOR EACH ROW EXECUTE FUNCTION public.proc_guard(); CREATE TRIGGER proc_request_guard BEFORE UPDATE ON public.proc_purchase_requests FOR EACH ROW EXECUTE FUNCTION public.proc_guard(); CREATE TRIGGER proc_order_guard BEFORE UPDATE ON public.proc_purchase_orders FOR EACH ROW EXECUTE FUNCTION public.proc_guard();
CREATE OR REPLACE FUNCTION public.proc_transition_order(_id UUID,_to public.proc_order_status,_note TEXT DEFAULT NULL) RETURNS public.proc_purchase_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.proc_purchase_orders; n public.proc_purchase_orders; ok BOOLEAN; BEGIN SELECT * INTO r FROM public.proc_purchase_orders WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT public.proc_can_approve(r.company_id) THEN RAISE EXCEPTION 'Procurement approval role required'; END IF; ok:=CASE r.status::text WHEN 'draft' THEN _to::text='submitted' WHEN 'submitted' THEN _to::text IN ('approved','rejected') WHEN 'approved' THEN _to::text='ordered' WHEN 'ordered' THEN _to::text IN ('partially_received','completed','cancelled') WHEN 'partially_received' THEN _to::text IN ('completed','cancelled') ELSE false END; IF NOT ok THEN RAISE EXCEPTION 'Illegal purchase order transition'; END IF; PERFORM set_config('proc.workflow','on',true); UPDATE public.proc_purchase_orders SET status=_to,ordered_at=CASE WHEN _to='ordered' THEN now() ELSE ordered_at END WHERE id=_id RETURNING * INTO n; PERFORM public.proc_log(r.company_id,'purchase_order',r.id,'transition',jsonb_build_object('from',r.status,'to',_to,'note',_note)); RETURN n; END; $$;
REVOKE ALL ON FUNCTION public.proc_log(UUID,TEXT,UUID,TEXT,JSONB) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.proc_transition_order(UUID,public.proc_order_status,TEXT) TO authenticated;
